export function resolveIconKey(rawName?: string): string | null {
  if (!rawName) return null
  const cleaned = rawName.toLowerCase().replace(/[-_\s]/g, "")
  if (iconNodes[cleaned]) return cleaned
  if (iconAliases[cleaned] && iconNodes[iconAliases[cleaned]]) return iconAliases[cleaned]
  return null
}
